#include "stdafx.h"#include "HcdPool.h"#include <rsuErr.h>#include <stdlib.h>#include <macros/StrHelps.h>using namespace nRSUx;KHcdPool::KHcdPool(): m_Count( 0 ), m_ActiveI( 0 ){  ZeroMemory( m_Hcdes, sizeof(m_Hcdes) );}int KHcdPool::GetCount(){  return m_Count;}typeHASH32_ KHcdPool::Register( IHcdServer *pStn, LPCSTR pszPrjName, LPCSTR pszObjName ){  ASS( m_Count<_countof(m_Hcdes) );  if( m_Count==_countof(m_Hcdes) )    return 0;  m_Hcdes[m_Count].pServer = pStn;  m_Hcdes[m_Count].pPrjName = pszPrjName;  m_Hcdes[m_Count].pszObjName = pszObjName;  m_Hcdes[m_Count].CRC = CreateHASH16( pszPrjName );  for( int i=0; i<m_Count; ++i )  {    ASSD( m_Hcdes[m_Count].CRC != m_Hcdes[i].CRC );  }  return m_Hcdes[m_Count++].CRC;}nRSUx::SParamInfo KHcdPool::GetObj( LPCSTR pszPointName, LPSTR pszIOtype, LPCSTR pSuffix ){  nRSUx::SParamInfo info;  char buf[2][64];  SplitString( pszPointName, buf, '.', false );  for( int i=0; i<m_Count; ++i )  {    if( _strcmpi( m_Hcdes[i].pPrjName, pSuffix) )      continue;    IHcdElement *pEl = m_Hcdes[i].pServer->FindObj( buf[0] );    if( !pEl )      break;    eHcdVType Type = ehtHZ;    tHcdVarSizeType_ VarSize = 0;    BYTE *pMem = pEl->GetField( buf[1], &Type, &VarSize );    if( pMem )    {      switch( Type )      {      case ehtDigital32:        info << (int*)pMem;        break;      case ehtAnalog32:        info << (float*)pMem;        break;      case ehtBool:        info << (bool*)pMem;        break;      default:        ASSD(0);        break;      }      break;    }  }  return info;}/*BYTE* KHcdPool::GetVar( LPCSTR pszPrjName, LPSTR pszPointName, eVarType *pType, tVarSizeType_ *pVarSize ){  for( int i=0; i<m_Count; ++i )  {    if( _strcmpi( m_Hcdes[i].pPrjName, pszPrjName) )      continue;    BYTE *pMem = m_Hcdes[i].pHcd->GetVar( pszPointName, pType, pVarSize );    return pMem;  }  return NULL;}bool KHcdPool::GetFirstACSObject(){  m_ActiveI = 0;  if( !m_Count )    return false;  return m_Hcdes[m_ActiveI].pHcd->GetFirstACSObject();}bool KHcdPool::GetNextACSObject( void ** pData, char *Name, size_t sn, char *Data, size_t sd ){  if( !m_Count )    return false;  bool r = m_Hcdes[m_ActiveI].pHcd->GetNextACSObject( pData, Name, sn, Data, sd );  if( !r )  {    while( 1 )    {      ++m_ActiveI;      if( m_ActiveI>=m_Count )        return false;      r = m_Hcdes[m_ActiveI].pHcd->GetFirstACSObject();      if( !r )        continue;      r = m_Hcdes[m_ActiveI].pHcd->GetNextACSObject( pData, Name, sn, Data, sd );      if( !r )        continue;      break;    }  }  return r;}bool KHcdPool::ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData ){  for( int i=0; i<m_Count; ++i )  {    if( _strcmpi(Name, m_Hcdes[i].pPrjName) )    {      if( _strcmpi(Name, m_Hcdes[i].pszObjName) )        continue;    }    bool r = m_Hcdes[i].pHcd->ShowACSObject( pInfo, hMainWnd, m_Hcdes[i].pPrjName, pData );    if( r )      return r;  }  return false;}*/